use super::*;
use kira::{AudioManager as KiraManager, AudioManagerSettings};
use shin_audio::test_support::{MockBackendSettings, SampleBackend as MockBackend};
use shin_core::vm::command::types::AudioWaitStatus;

/// Read actual frozen native packets/states, skipping full owner snapshots and
/// unused uniforms. The data is generated by original instructions, not Rust.
fn parse_native_states(output: &str) -> Vec<(usize, [u64; 26])> {
    let mut states = Vec::new();
    for row in output.lines() {
        let words: Vec<_> = row.split_whitespace().collect();
        assert_eq!(words[0], "N");
        let profile = words[1].parse().unwrap();
        let mut i = 4;
        while i < words.len() {
            let tag = words[i];
            i += 1;
            let count = match tag {
                "O" => {
                    let count = 338;
                    assert_eq!(words[i + count], "D");
                    assert_eq!(words[i + count + 1], "7");
                    let derived: usize = words[i + count + 2].parse().unwrap();
                    i += count + 3 + derived;
                    continue;
                }
                "w" => 4 + 3 * words[i + 3].parse::<usize>().unwrap(),
                "M" | "J" | "K" | "F" | "Q" | "l" | "r" => 2,
                "W" | "A" | "B" | "h" | "y" => 3,
                "p" | "b" | "v" | "a" | "q" | "f" | "j" => 1,
                "N" | "n" | "T" | "Z" => 4,
                "S" => 5,
                "D" => 113,
                "E" => 9,
                "P" => {
                    let state: [u64; 26] =
                        std::array::from_fn(|offset| words[i + offset].parse().unwrap());
                    states.push((profile, state));
                    26
                }
                _ => panic!("Unknown native Movie tag {tag} in profile {profile}"),
            };
            i += count;
        }
        assert_eq!(i, words.len());
    }
    states
}
fn native_states() -> Vec<(usize, [u64; 26])> {
    parse_native_states(include_str!(
        "../../../reverse-engineering/higurashi/live-movie-capture/output.txt"
    ))
}

#[test]
fn native_901_status_snapshots_require_both_eof_and_pcm_drain_without_deadline() {
    let states = native_states();
    assert_eq!(states.len(), 901);
    for (profile, state) in states {
        assert_eq!(
            native_status(state[3] != 0, state[6] != 0, state[7] != 0 && state[8] == 0),
            state[0] as u32,
            "Native Movie status profile {profile}"
        );
    }
    // Huge wall time is not a completion condition; a paused final texture
    // remains available after the original EOF+audio-drain status reaches2.
    assert_eq!(native_status(false, false, true), 1);
}

fn synthetic_frame(index: u32, pts_us: u64) -> Frame<u32> {
    Frame {
        timing: FrameTiming {
            frame_number: index,
            start_time: pts_us,
            duration: 100,
        },
        pts_us,
        payload: index,
    }
}

#[test]
fn native_first_future_frame_selection_retains_last_frame_through_pause_and_eof() {
    // Actual original Q0/100,Q1/200,Q2/300 and clocks50/150/250/350.
    // Profile104 is the audio-free original queue/callback case in frozen corpus.
    let original: Vec<_> = native_states()
        .into_iter()
        .filter_map(|(profile, state)| {
            (profile == 104 && state[9] != 0).then_some((state[21], state[10], state[0]))
        })
        .collect();
    assert_eq!(
        &original[..4],
        &[(50, 0, 1), (150, 1, 1), (250, 2, 2), (350, 2, 2)]
    );
    let mut frames = Frames::new(synthetic_frame(0, 100));
    frames.queue.push_back(synthetic_frame(1, 200));
    frames.queue.push_back(synthetic_frame(2, 300));
    frames.eof = true;
    for (clock, id, status) in &original[..4] {
        let selected = frames.select(*clock).unwrap();
        assert_eq!(u64::from(selected.payload), *id);
        let timing = selected.timing;
        frames.presented(timing);
        assert_eq!(
            native_status(false, frames.terminal_presented, true),
            *status as u32
        );
    }
    assert_eq!(frames.queue.len(), 1);
    assert_eq!(frames.select(u64::MAX).unwrap().payload, 2);
    assert_eq!(frames.displayed.unwrap().frame_number, 2);
}

#[test]
fn native_64_frame_clock_jump_polls_through_elapsed_output_without_a_read_cap() {
    // NEW capture executes the frozen original player with all64 decoded
    // frames queued, then jumps directly across25 and60 earlier frames.
    let original: Vec<_> = parse_native_states(include_str!(
        "../../../reverse-engineering/higurashi/live-movie-jump-capture/output.txt"
    ))
    .into_iter()
    .filter_map(|(_, state)| (state[9] != 0).then_some((state[21], state[10], state[0])))
    .collect();
    assert_eq!(
        &original[..3],
        &[(2550, 25, 1), (6050, 60, 1), (6400, 63, 2)]
    );
    assert!(original[3..].iter().all(|state| *state == (6400, 63, 2)));
    let mut frames = Frames::new(synthetic_frame(0, 100));
    let mut transport: VecDeque<_> = (1..64)
        .map(|index| synthetic_frame(index, u64::from(index + 1) * 100))
        .collect();
    for (step, &(clock, expected, status)) in original[..3].iter().enumerate() {
        let mut polled = 0;
        refill_first_future(&mut frames, clock, || {
            polled += 1;
            Ok(transport
                .pop_front()
                .map_or(FramePoll::Eof, FramePoll::Frame))
        })
        .unwrap();
        if step == 0 {
            assert!(
                polled > 16,
                "A buffered future frame must not wait for another update"
            );
        }
        assert!(
            frames.queue.len() <= 2,
            "Only candidate and lookahead are retained"
        );
        let chosen = frames.select(clock).unwrap();
        assert_eq!(u64::from(chosen.payload), expected);
        let timing = chosen.timing;
        frames.presented(timing);
        assert_eq!(
            native_status(false, frames.terminal_presented, true),
            status as u32
        );
    }
    assert!(transport.is_empty());
    refill_first_future(&mut frames, u64::MAX, || {
        panic!("Retained EOF never repolls decoder")
    })
    .unwrap();
    assert_eq!(frames.select(u64::MAX).unwrap().payload, 63);
}

#[test]
fn nonblocking_starvation_retains_candidate_and_distinguishes_later_eof() {
    let mut frames = Frames::new(synthetic_frame(0, 100));
    let mut transport = VecDeque::from([
        FramePoll::Frame(synthetic_frame(1, 200)),
        FramePoll::Pending,
    ]);
    refill_first_future(&mut frames, 150, || Ok(transport.pop_front().unwrap())).unwrap();
    assert_eq!(frames.select(150).unwrap().payload, 1);
    let timing = frames.queue.front().unwrap().timing;
    frames.presented(timing);
    assert!(!frames.eof);
    assert!(!frames.terminal_presented);
    refill_first_future(&mut frames, 150, || Ok(FramePoll::Eof)).unwrap();
    frames.refresh_terminal();
    assert!(frames.terminal_presented);
}

#[test]
fn supplied_b_frame_movies_match_normalized_presentation_time_in_actual_codec_order() {
    // Independent CTTS/edit tables plus real FFprobe output packet positions
    // supply this trace. Every14 asset decodes128 packets, contributing its
    // first96 outputs while excluding the artificial EOF flush tail.
    // The shared ordinal timestamp grid is compatible for these files because
    // their sorted CTTS grid starts at the authored video edit origin2002.
    let trace = include_str!("../../../reverse-engineering/higurashi/live-movie-codec-order.tsv");
    let mut movies = std::collections::HashSet::new();
    let mut comparisons = 0;
    let mut reordered = 0;
    for line in trace.lines().filter(|line| !line.starts_with('#')) {
        let fields: Vec<_> = line.split_whitespace().collect();
        assert_eq!(fields.len(), 7);
        movies.insert(fields[0]);
        let timescale: u32 = fields[1].parse().unwrap();
        let edit_origin: u64 = fields[2].parse().unwrap();
        let duration: u64 = fields[3].parse().unwrap();
        let ordinal: u64 = fields[4].parse().unwrap();
        let decode_index: u64 = fields[5].parse().unwrap();
        let composition_pts: u64 = fields[6].parse().unwrap();
        let original_normalized = composition_pts.checked_sub(edit_origin).unwrap();
        assert_eq!(
            pts_micros(ordinal * duration, timescale).unwrap(),
            pts_micros(original_normalized, timescale).unwrap(),
            "Supplied Movie{} presentation output{} from sample{}",
            fields[0],
            ordinal,
            decode_index
        );
        reordered += usize::from(ordinal != decode_index);
        comparisons += 1;
    }
    assert_eq!(movies.len(), 14);
    assert_eq!(comparisons, 1344);
    assert!(reordered > 0, "Real B-frame reordering is covered");
}

#[test]
fn independent_microsecond_clock_ignores_layer_delta_and_preserves_pause_origin() {
    let now = Arc::new(std::sync::atomic::AtomicU64::new(0));
    let source = now.clone();
    let mut clock = WallClock::new(Arc::new(move || source.load(Ordering::Acquire)));
    now.store(100, Ordering::Release);
    assert_eq!(clock.time(), 0, "Prepared player has no elapsed time");
    clock.set_running(true);
    now.store(350, Ordering::Release);
    assert_eq!(clock.time(), 250);
    clock.set_running(false);
    now.store(1_000_000_000, Ordering::Release);
    assert_eq!(clock.time(), 250);
    clock.set_running(false);
    clock.set_running(true);
    now.store(1_000_000_111, Ordering::Release);
    assert_eq!(clock.time(), 361);
    assert_eq!(pts_micros(9_000, 90_000).unwrap(), 100_000);
    assert!(pts_micros(10, 0).is_err());
}

struct FinitePcm {
    frames: u32,
    position: u32,
    value: f32,
    failed: Arc<AtomicBool>,
}
impl AudioFrameSource for FinitePcm {
    fn is_failed(&self) -> bool {
        self.failed.load(Ordering::Acquire)
    }
    fn max_frame_size(&self) -> usize {
        6
    }
    fn sample_rate(&self) -> u32 {
        1000
    }
    fn pre_skip(&self) -> u32 {
        2
    }
    fn pre_roll(&self) -> u32 {
        2
    }
    fn read_frame(&mut self, destination: &mut AudioBuffer) -> bool {
        if self.is_failed() || self.frames == 0 {
            return false;
        }
        self.frames -= 1;
        self.position += 6;
        destination.extend(std::iter::repeat_n((self.value, self.value), 6));
        true
    }
    fn samples_seek(&mut self, _position: u32) -> Result<u32> {
        anyhow::bail!("not a looping source")
    }
    fn current_sample_position(&self) -> u32 {
        self.position
    }
}
fn pcm_source(value: f32) -> HigurashiAudioSource<FinitePcm> {
    HigurashiAudioSource::new(FinitePcm {
        frames: 3,
        position: 0,
        value,
        failed: Arc::new(AtomicBool::new(false)),
    })
}
fn settings() -> AudioSettings {
    AudioSettings {
        paused: true,
        fade_in: Tween::IMMEDIATE,
        loop_start: None,
        loop_count: 0,
        volume: Volume(1.0),
        pan: Pan::default(),
        playback_rate: 1.0,
    }
}

#[test]
fn actual_mixer_drains_real_pcm_including_silence_and_retains_the_media_clock() {
    for value in [0.0, 0.25] {
        let mut manager = KiraManager::<MockBackend>::new(AudioManagerSettings {
            backend_settings: MockBackendSettings { sample_rate: 1000 },
            internal_buffer_size: 1,
            ..Default::default()
        })
        .unwrap();
        let source = pcm_source(value);
        let tail = source.tail.clone();
        let handle = manager
            .play(AudioData {
                source,
                settings: settings(),
            })
            .unwrap();
        for _ in 0..30 {
            manager.backend_mut().on_start_processing();
            assert_eq!(manager.backend_mut().process(), kira::Frame::ZERO);
        }
        assert!(!tail.eof.load(Ordering::Acquire));
        assert_eq!(handle.position_micros(), 0);
        handle.set_paused(false);
        let mut observed_eof_before_drain = false;
        let mut audible = false;
        for _ in 0..80 {
            manager.backend_mut().on_start_processing();
            let sample = manager.backend_mut().process();
            audible |= sample.left != 0.0;
            if tail.eof.load(Ordering::Acquire) && !tail.drained(handle.drained_position_samples())
            {
                observed_eof_before_drain = true;
            }
        }
        assert_eq!(audible, value != 0.0);
        assert!(
            observed_eof_before_drain,
            "AAC EOF must not replace actual PCM drain"
        );
        assert_eq!(
            tail.terminal.load(Ordering::Acquire),
            16,
            "18 raw samples minus codec pre-skip2"
        );
        assert!(tail.drained(handle.drained_position_samples()));
        let completed_clock = handle.position_micros();
        assert!(handle.get_wait_status().contains(AudioWaitStatus::PLAYING));
        for _ in 0..40 {
            manager.backend_mut().on_start_processing();
            assert_eq!(manager.backend_mut().process(), kira::Frame::ZERO);
        }
        assert!(handle.position_micros() > completed_clock);
        handle.set_paused(true);
        manager.backend_mut().on_start_processing();
        let paused = handle.position_micros();
        for _ in 0..20 {
            manager.backend_mut().on_start_processing();
            assert_eq!(manager.backend_mut().process(), kira::Frame::ZERO);
        }
        assert_eq!(handle.position_micros(), paused);
        handle.stop_immediate();
        for _ in 0..20 {
            manager.backend_mut().on_start_processing();
            let _ = manager.backend_mut().process();
        }
        assert_eq!(manager.main_track().num_sounds(), 0);
    }
}

#[test]
fn decoder_failure_is_not_normal_pcm_eof_and_does_not_publish_fake_drain() {
    let mut source = pcm_source(0.25);
    source.source.failed.store(true, Ordering::Release);
    let mut destination = AudioBuffer::with_capacity(100);
    assert!(!source.read_frame(&mut destination));
    assert!(source.is_failed());
    assert!(!source.tail.eof.load(Ordering::Acquire));
    assert!(!source.tail.drained(u32::MAX));
    assert!(source.samples_seek(0).is_err());
}

#[test]
fn eof_is_not_visible_until_final_retained_frame_is_presented_and_nv12_is_validated() {
    let mut frames = Frames::new(synthetic_frame(0, 100));
    frames.queue.push_back(synthetic_frame(1, 200));
    frames.presented(FrameTiming {
        frame_number: 0,
        start_time: 100,
        duration: 100,
    });
    frames.eof = true;
    frames.refresh_terminal();
    assert!(!frames.terminal_presented);
    let final_timing = frames.select(150).unwrap().timing;
    frames.refresh_terminal();
    assert!(
        !frames.terminal_presented,
        "Last frame must be delivered to the RGBA stage"
    );
    frames.presented(final_timing);
    assert!(frames.terminal_presented);
    let mut frame = Nv12Frame {
        size: dpi::PhysicalSize::new(2, 2),
        y_plane: vec![0; 4],
        uv_plane: vec![128; 2],
    };
    assert!(validate_frame(&frame).is_ok());
    frame.uv_plane.pop();
    assert!(validate_frame(&frame).is_err());
    frame.size.width = 3;
    assert!(validate_frame(&frame).is_err());
}
